INSERT INTO recipes VALUES(1,'저칼륨 배추 고기 롤','배추를 삶아 칼륨을 대폭 줄였으며, 소량의 고단백 소고기로 근육 손실을 방지함','/static/001.png','신부전','한식','고기','알배기 배추,다진 소고기,양파,참기름,설탕',180,50.0,10.0,14.0,45.0,30,replace('1. 배추와 다진 양파는 끓는 물에 10분 이상 삶아 칼륨을 제거한 후 찬물에 헹궈 물기를 짭니다.\n2. 다진 소고기에 설탕, 참기름으로 밑간을 합니다.\n3. 삶은 배추 잎에 고기 반죽을 넣고 돌돌 맙니다.\n4. 찜기에 넣고 15분간 쪄냅니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(2,'맑은 무 계란 흰자 국','인 함량이 높은 노른자를 제외하고 순수 단백질인 흰자만 사용해 신장 부담을 최소화함','/static/002.png','신부전','한식','고단백','무,계란 흰자,대파,참기름',95,30.0,8.0,5.0,45.0,150,replace('1. 무는 얇게 썰어 물에 2시간 담갔다가 끓는 물에 데쳐냅니다.\n2. 냄비에 물을 붓고 무를 넣어 끓이다가 계란 흰자를 줄을 치듯 풀어 넣습니다.\n3. 소금 대신 식초 한 방울과 참기름으로 풍미를 냅니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(3,'레몬 허브 대구찜','붉은 고기보다 인 함량이 낮은 흰살생선과 짠맛 없이 입맛을 돋우기 위해 레몬을 사용함','/static/003.png','신부전','양식','고단백','대구 살, 레몬즙, 로즈마리, 올리브유',130,10.0,12.0,4.0,60.0,50,replace('1. 대구 살은 물에 30분 담가 혈액과 염분을 제거합니다.\n2. 레몬즙과 올리브유를 섞어 생선에 바릅니다.\n3. 허브를 올리고 종이 호일에 싸서 오븐이나 찜기에서 굽습니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(4,'양파 파프리카 당면 볶음','백질은 거의 없으면서 전분과 기름을 환자에게 꼭 필요한 열량을 공급함','/static/004.png','신부전','한식','','당면,양파,파프리카,식용유, 설탕',220,15.0,1.0,5.0,0.0,140,replace('1. 모든 채소는 채 썰어 물에 2시간 담근 후 데쳐냅니다.\n2. 당면은 삶아서 물기를 뺍니다.\n3. 팬에 기름을 넉넉히 두르고 채소와 당면을 볶으며 설탕과 식초로 맛을 냅니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(5,'소고기 채소 무나물','무는 칼륨이 적은 대표적인 채소이며, 들의 불포화지방산이 혈관 건강을 도움','/static/005.png','신부전','한식','고기','무소고기,들기름',110,10.0,5.0,10.0,0.0,20,replace('1. 무는 채 썰어 끓는 물에 충분히 데칩니다.\n2. 팬에 들기름을 두르고 소고기를 볶다가 무를 넣고 함께 볶습니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(6,'블루베리 견과류 오트밀','오트밀의 수용성 식이섬유(베타글루칸)가 혈중 콜 출합니다.','/static/006.png','대사증후군','','채식(비건)','롤드 오츠, 무가당 , 냉동 블루베리, 호두,몬 가루',280,35.0,10.0,12.0,0.0,20,replace('1. 냄비에 두유와 오트밀을 넣고 중불에서 저어가며 5분간 끓입니다.\n2. 오트밀이 부드러워지면 그릇에 담습니다.\n3. 블루베리나 부순 호두를 올리고 시나몬 가루를 뿌립니다.','\n',char(10)));
INSERT INTO recipes VALUES(7,'연어 아스파라거스 구이','오메가-3 지방산이 간의 염증을 줄이곡 혈전 형성을 억제함','/static/007.png','대사증후군','양식','해산물','연어 필렛, 아스파라거스방울토마토, 올리브유, 레몬즙',350,5.0,30.0,22.0,0.0,30,replace('1. 연어에 레몬즙과 후추를 뿌려 밑간합니다.\n\n2. 에어프라이어 바스켓에 연어, 아스파라거스, 토마토를 넣고 올리브유를 고루 바릅니다.\n\n3. 180°C에서 12~15분간 굽습니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(8,'두부 보리빔밥','보리는 백미보다 GI 지수가 낮아 인슐린 저항성 개선에 탁월함','/static/008.png','대사증후군','한식','고단백','두부,상추,깻잎,당근채,들기름,저염간장소스',320,45.0,15.0,10.0,0.0,20,replace('1. 두부는 끓는 물에 데친 후 칼등으로 으깨어 팬에서 수분을 날리듯 볶습니다.\n2. 각종 채소는 가늘게 채 썹니다.\n3. 보리밥 위에 채소와 으깬 두부를 올리고 들기름과 저염 간장으로 비빕니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(9,'닭가슴살 브로콜리 볶음','고단백 저지방 식단으로 대사율을 높임','/static/009.png','대사증후군','샐러드','고단백','닭가슴살,브로콜리,마늘,굴소스',240,10.0,30.0,5.0,0.0,20,replace('1. 닭가슴살은 한입 크기로 썰고, 브로콜리는 살짝 데칩니다. \n2. 팬에 기름을 아주 살짝 두르고 편마늘을 볶아 향을 냅니다.\n3. 닭가슴살을 넣어 익히다 브로콜리와 굴소스를 넣고 빠르게 볶아 마무리합니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(10,'병아리콩 아보카도 샐러드','아보카도의 불포화 지방이 나쁜 콜레스테롤(LDL)낮춥니다.','/static/010.png','대사증후군','샐러드','고단백','병아리콩,아보카도,오이,발사믹 식초',310,28.0,9.0,18.0,0.0,20,replace('1. 아보카도와 오이를 큐브 모양으로 썹니다.\n2. 볼에 병아리콩과 손질한 재료를 담습니다.\n3. 발사믹 식초와 후추를 뿌려 가볍게 버무립니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(11,'고등어조림','이 레시피는 혈당 스파이크를 방지하기 위해 설탕 대신 알룰로스를 사용하고, 나트륨 배출을 돕는 무를 충분히 활용하는 것이 핵심입니다.','/static/011.png','당뇨','한식','해산물','주재료: 고등어 1토막(약 100g), 무 150g (넉넉히 넣어 포만감 유지), 양파 1/4개(50g), 대파 1/3대(20g),양념장:(저염 간장 1.5큰술,고춧가루 1큰술,알룰로스 1큰술 (설탕 대신 사용),다진 마늘 0.5큰술, 다진 생강 약간,물 또는 멸치 육수 200ml',270,21.0,22.0,11.0,1310.0,90,replace('1. 재료 손질 및 비린내 제거\n고등어: 흐르는 물에 깨끗이 씻은 후, 식초를 1큰술 푼 물이나 쌀뜨물에 5~10분 정도 담가두세요. (비린내를 잡고 살을 단단하게 해줍니다.) 이후 물기를 닦아 준비합니다.\n\n무: 1cm 두께의 반달 모양으로 썹니다. 당뇨 식단에서는 무가 훌륭한 식이섬유 공급원이 되므로 넉넉히 준비하세요.\n\n부재료: 양파는 굵게 채 썰고, 대파와 청양고추(선택)는 어슷하게 썹니다.\n\n2. 양념장 만들기\n작은 볼에 저염 간장 1.5큰술, 고춧가루 1큰술, 알룰로스 1큰술, 다진 마늘 0.5큰술, 다진 생강 약간, 후추를 섞어 미리 만들어 둡니다.\n\nTip: 양념을 미리 섞어두면 고춧가루가 불어 색이 더 고와지고 맛이 겉돌지 않습니다.\n\n3. 냄비에 담기 및 끓이기\n바닥 깔기: 냄비 바닥에 손질한 무를 넓게 깝니다. 무를 먼저 깔아야 고등어가 바닥에 눌어붙지 않고 무의 시원한 맛이 국물에 잘 우러납니다.\n\n재료 올리기: 무 위에 고등어를 올리고, 그 위에 양파를 얹습니다.\n\n양념 붓기: 준비한 양념장을 고등어 위에 골고루 끼얹은 뒤, 물(또는 멸치 육수) 200ml를 냄비 가장자리로 살살 붓습니다.\n\n4. 조리 단계 (불 조절이 중요!)\n초반 (강불): 뚜껑을 연 상태로 강불에서 끓입니다. (비린내 성분이 증기와 함께 날아갑니다.)\n\n중반 (중약불): 국물이 끓어오르면 뚜껑을 덮고 중약불에서 15~20분간 뭉근하게 조립니다. 이때 중간중간 국물을 숟가락으로 떠서 고등어 위에 끼얹어주세요.\n\n마무리: 무가 투명하게 익고 국물이 자작하게 줄어들면 대파를 넣고 1~2분 더 끓여 마무리합니다.','\n',char(10)));
INSERT INTO recipes VALUES(12,'맥적구이',replace('된장을 베이스로 하여 돼지고기의 풍미를 살린 저당, 저염 맥적구이입니다.\n\n식이섬유 보충: 함께 드시는 부추와 양파는 돼지고기의 단백질 흡수를 돕고 혈당이 천천히 오르도록 돕습니다. 부족하다면 쌈채소(상추, 깻잎)를 곁들여 드시면 더욱 좋습니다.\n\n 현미밥이나 잡곡밥을 곁들여 탄수화물 섭취 속도를 조절해 주세요.','\n',char(10)),'/static/012.png','당뇨','한식','고기','주재료: 돼지고기(뒷다리살 또는 안심 등 지방이 적은 부위) 120g, 부추 30g, 양파 1/4개(50g),된장 1큰술 (가급적 저염 된장 사용),알룰로스 1큰술 (설탕 대용),다진 마늘 0.5큰술,맛술 1큰술 (청주로 대체 가능),참기름 0.5작은술, 생강가루/후추 약간',245,14.0,27.0,9.0,820.0,60,replace('1. 고기 손질: 돼지고기는 0.5cm 두께의 한입 크기로 썰어준 뒤, 칼등으로 가볍게 두드려 육질을 부드럽게 만듭니다.\n\n2. 재우기: 분량의 양념장 재료를 모두 섞은 뒤 고기에 골고루 버무려 냉장고에서 20~30분 정도 숙성시킵니다. (된장의 풍미가 배어들고 육질이 연해집니다.)\n\n3. 채소 준비: 부추는 5cm 길이로 썰고, 양파는 얇게 채 썹니다.\n\n4. 굽기: 달궈진 팬에 기름을 아주 살짝만 두르고 양념한 고기를 올립니다. 양념 때문에 타기 쉬우므로 중약불에서 속까지 충분히 익힙니다.\n\n5. 마무리: 고기가 거의 다 익었을 때 채 썬 양파를 넣고 함께 볶다가, 마지막에 불을 끄고 부추를 넣어 잔열로 살짝만 익혀 완성합니다.','\n',char(10)));
INSERT INTO recipes VALUES(13,'숙주 미나리 볶음','식이섬유가 풍부하면서도 전처리를 통해 칼륨 위낮춘 반찬입니다.','/static/013.png','신부전','한식','채식(비건)','숙주 50g,마늘 소량,용유',65,0.0,0.0,0.0,0.0,20,replace('1. 숙주와 미나리를 끓는 물에 데쳐 칼륨을 제거합니다.\n2. 마늘 향을 낸 기름에 빠르게 볶아 아삭함을 살립니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(14,'애호박 양파 들기름 볶음','고소한 들기름 향이 소금의 빈자리를 채워줍니다.','/static/014.png','신부전','한식','채식(건)','애호박 40g, 양파 30g, 들기름, 설탕',85,0.0,0.0,0.0,0.0,20,replace('1. 애호박은 반달썰기, 양파는 채 썰어 물에 담갔다 데칩니다.\n2. 들기름에 볶아 고소한 맛을 강조합니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(15,'가지 식초 나물','신부전 환자는 산미(식초)를 활용하면 나트륨 섭취를 줄이기 쉽습니다.','/static/015.png','신부전','한식','채식(비건)','가지 50g, 식초, 설탕, 참기름',55,0.0,0.0,0.0,0.0,20,replace('1. 가래떡을 먹기 좋게 썰어 팬에 기름을 두르고 굽습니다.\n2. 꿀을 발라 달콤하게 마무리합니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(16,'닭안심 마늘 레몬 구이','껍질 없는 닭안심은 저지방 고단백 식품으로 신장 여과 기능에 무리를 덜 줍니다.','/static/016.png','신부전','한식','가금류','닭안심 50g, 마늘 2알, 레몬즙, 올리브유',145,0.0,11.0,0.0,55.0,20,replace('1. 가지를 썰어 쪄낸 후 물기를 살짝 짭니다.\n2. 식초와 설탕을 1:1 비율로 섞어 버무립니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(17,'버섯 들깨탕','질환 도움: 지방간 & 면역력. 버섯의 식이섬유와 들깨의 리놀렌산이 간 기능을 돕고 혈액을 맑게 합니다.','/static/017.png','대사증후군','한식','채식(비건)','표고/느타리버섯 150g, 들깨가루 3큰술, 멸치 육수 500ml, 다진 마늘',180,12.0,6.0,14.0,0.0,20,replace('1. 닭안심은 삶아서 결대로 찢어 칼륨을 뺍니다.\n2. 팬에 올리브유와 편마늘을 볶다가 닭안심을 넣고 레몬즙을 뿌려 마무리합니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(18,'고등어 채소 찜','질환 도움: 중성지방 저하. 등푸른생선의 EPA/DHA는 혈관 청소부 역할을 합니다.','/static/018.png','대사증후군','한식','해산물','고등어 1토막, 무 100g, 대파, 양파, 고춧가루 1큰술, 다진 마늘',290,8.0,22.0,18.0,0.0,20,replace('1. 냄비 바닥에 도톰하게 썬 무를 깝니다.\n2. 그 위에 고등어와 채소, 양념장을 올리고 물을 자작하게 붓습니다.\n3. 무가 푹 익을 때까지 약불에서 조립니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(19,'실곤약 야채 비빔면','질환 도움: 비만 극복. 칼로리가 거의 없는 곤약으로 포만감은 채우고 당질 섭취는 극단적으로 낮춥니다.','/static/019.png','대사증후군','한식','채식(비건)','실곤약 200g, 오이, 당근, 양배추, 삶은 달걀 1/2개, 비빔 양념(알룰로스 사용).',120,15.0,7.0,4.0,0.0,20,replace('1. 실곤약은 끓는 물에 식초를 넣고 살짝 데쳐 특유의 냄새를 제거합니다.\n2. 채소를 채 썰어 곤약과 섞습니다.\n3. 설탕 대신 알룰로스를 넣은 양념장에 비벼 달걀을 올립니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(20,'그릭 요거트 아마씨 가루','질환 도움: 장내 미생물 개선 & 대사 촉진. 유익균은 비만 억제에 도움을 주며 아마씨는 여성 대사 건강에 좋습니다.','/static/020.png','대사증후군','','채식(비건)','무설탕 그릭 요거트 100g, 아마씨 가루 1큰술, 아몬드 슬라이스 약간',190,6.0,12.0,13.0,0.0,20,replace('1. 그릇에 요거트를 담습니다.\n2. 아마씨 가루와 아몬드를 뿌려 섞어 먹습니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(21,'대구살 파피요트(종이호일 찜)','질환 도움: 간 건강 & 저칼로리. 흰살생선은 간에 부담을 주지 않는 양질의 단백질원입니다.','/static/021.png','대사증후군','','해산물','대구살 150g, 그린빈, 방울토마토, 레몬, 올리브유',210,4.0,28.0,9.0,0.0,20,replace('1. 종이호일 위에 대구살과 채소를 올립니다.\n2. 올리브유 한 큰술과 허브를 뿌린 후 호일을 사탕 봉지처럼 감쌉니다.\n3. 에어프라이어 190°C에서 15분간 익힙니다.\n','\n',char(10)));
INSERT INTO recipes VALUES(23,'봄나물 아롱사태 초밥','식이섬유가 풍부한 현미와 봄나물, 설탕 대용인 그린스위트를 사용하고 기름기를 뺀 고단백 아롱사태를 사용하여 혈당 스파이크를 예방하고 균형 잡힌 영양을 제공합니다.','/static/023.png','당뇨','한식','고기','쌀 70g, 현미 20g, 소고기 아롱사태 80g, 봄나물 70g,쌈장 5g (1/4큰술), 고추냉이 2g (1/2작은술), 참기름 2.5g (1/2작은술), 그린스위트 1g (1작은술),사과식초 15g (1큰술), 레몬 1~2방울',245,14.0,27.0,9.0,820.0,20,replace('1.고기 손질: 소고기 아롱사태는 30분 이상 흐르는 물에 담가 불순물을 제거합니다.\n\n2. 데치기: 끓는 물에 고기를 넣고 데친 후, 얼음물에 담가 기름기를 최대한 제거합니다.\n\n3. 삶기: 끓는 물에 아롱사태를 20~30분가량 삶아서 준비합니다.\n\n4. 밥 양념: 고슬고슬하게 준비된 밥에 사과식초와 레몬을 첨가합니다.\n\n5. 나물 준비: 봄나물류는 끓는 소금물에 데친 후 얼음물에 담갔다가 흐르는 물에 2~3회 씻어 이물질을 제거하고 물기를 꼭 짭니다.\n\n6. 썰기: 삶은 아롱사태는 가로×세로 2x4cm 크기로 잘라 준비합니다.\n\n7. 모양 잡기: 봄나물은 송송 썰고, 현미 초밥(10g)을 한 입 크기로 뭉쳐서 준비합니다.\n\n8. 완성: 초밥 위에 준비된 양념을 살짝 바른 후 아롱사태를 올려 초밥을 만들고, 고명으로 봄나물을 뭉쳐 올려 마무리합니다.','\n',char(10)));
INSERT INTO recipes VALUES(24,'쭈꾸미 채소무침','칼로리 고단백 식품인 쭈꾸미와 식이섬유가 풍부한 봄동을 설탕 대신 그린스위트를 사용한 저당 드레싱으로 버무려, 혈당 스파이크를 방지하고 타우린 섭취를 돕는 건강한 식단입니다.','/static/024.png','당뇨','한식','해산물','쭈꾸미 100g, 봄동 70g, 깻잎 10g, 양파 10g,레몬즙 15g(1큰술), 소금 1g(1/3작은술), 후추 약간,고추장 10g(1/2큰술), 식초 7.5g(1/2큰술), 그린스위트 1.5g(1/2큰술), 다진 마늘 5g(1작은술), 올리브오일 5g(1작은술)',158,10.0,17.0,6.0,815.0,20,replace('1. 쭈꾸미 손질: 쭈꾸미는 내장을 제거한 후 밀가루를 넣고 바락바락 주물러 깨끗이 씻습니다. (내장은 머리와 다리 사이에 손을 넣고 살짝 잡아당기면 제거됩니다.)\n\n2. 데치기: 흐르는 물에 씻어준 쭈꾸미를 끓는 소금물에 넣어 살짝 데쳐냅니다.\n\n3. 밑간하기: 데친 쭈꾸미가 차게 식으면 한입 크기로 썰고, 레몬즙, 소금, 후추로 밑간을 합니다.\n\n4. 채소 손질: 봄동과 깻잎은 깨끗이 씻어 물기를 완전히 제거합니다.\n\n5. 썰기: 봄동은 한입 크기로 썰고, 깻잎과 양파는 곱게 채를 썰어 준비합니다.\n\n6. 드레싱 만들기: 고추장, 식초, 그린스위트, 다진 마늘, 올리브오일을 분량대로 섞어 드레싱을 만듭니다. (마늘이 들어간 드레싱은 실온에 3시간 정도 두면 숙성되어 더 맛있습니다.)\n\n7. 버무리기: 준비된 쭈꾸미와 채소들을 드레싱에 골고루 버무려 완성합니다.','\n',char(10)));
INSERT INTO recipes VALUES(25,'오리전골','불포화지방산이 풍부한 오리 살코기와 다양한 채소, 버섯류를 활용하여 단백질과 식이섬유를 충분히 섭취할 수 있으며, 계피를 활용한 육수로 풍미를 더하면서도 나트륨 섭취를 줄인 건강식입니다.','/static/025.png','당뇨','한식','가금류','오리살 40g, 속배추 20g, 깻잎순 20g, 표고버섯 25g, 느타리버섯 25g, 양파 10g, 대파 10g, 당근 15g,무 35g, 통마늘 5g, 통후추 3g, 계피 10g, 소금 3g (1작은술)',145,7.0,12.0,8.0,1220.0,20,replace('1. 오리 손질: 오리는 30분 이상 물에 담가 핏물을 제거합니다.\n\n2. 초벌 삶기: 오리를 찬물에서부터 넣고 끓인 후, 익으면 건져냅니다. 그 물에 무, 통마늘, 통후추를 넣어 5분 정도 더 끓입니다.\n\n3. 육수 완성: 육수에서 채소를 건져낸 후 계피와 소금을 넣고 10여 분간 더 끓여 육수를 준비합니다. (채소류와 계피를 따로 두 번 끓이면 계피 향이 극대화됩니다.)\n\n4. 고기 준비: 건져낸 오리고기는 기름기가 많은 껍질을 벗겨서 준비합니다.\n\n5. 채소 데치기: 속배추와 깻잎순은 끓는 물에 데친 후 얼음물에 식혀 물기를 제거합니다.\n\n6. 채소 손질: 데친 속배추와 깻잎순은 한 입 크기로 돌돌 말아 준비하고, 버섯류도 한 입 크기로 썹니다.\n\n7. 세팅: 냄비에 준비한 채소, 당근, 버섯류를 둘러 담고 가운데에 오리살을 놓습니다.\n\n8. 끓이기: 준비된 육수를 붓고 한소끔 끓여 완성합니다.','\n',char(10)));
INSERT INTO recipes VALUES(26,'양파 닭안심찜','천연 인슐린이라 불리는 이눌린이 풍부한 양파를 주재료로 하고, 지방이 적은 고단백 닭안심을 채워 넣어 혈당 조절과 근육 유지에 도움을 주는 저지방 고단백 식단입니다.','/static/026.png','당뇨','한식','가금류','양파 70g, 닭안심 40g, 녹말가루 15g, 물녹말 1작은술,소금 1g(1/3작은술), 다진 마늘 2.5g(1/2작은술), 다진 생강 1.5g(1/3작은술), 다진 파 5g(1작은술), 청주 7.5g(1/2큰술), 후춧가루 약간,다시마물 100g(1/2컵), 간장 5g(1작은술), 맛술 15g(1큰술), 참기름 2.5g(1/2작은술)',165,20.0,12.0,4.0,640.0,20,replace('1. 양파 손질: 양파는 반으로 자른 후 가운데 홈이 생기도록 속을 떼어냅니다.\n\n2. 속재료 준비: 닭안심은 칼로 곱게 다진 후 분량의 양념을 넣고 잘 섞습니다. (믹서기에 갈아서 사용하면 편리하며, 우유에 20분 정도 담갔다 사용하면 냄새 제거에 좋습니다.)\n\n3. 속 채우기: 1의 양파 안쪽에 녹말가루를 가볍게 묻힌 후, 2의 양념한 닭안심 소를 꽉 채워 넣습니다.\n\n4. 조리기: 냄비에 찜양념을 넣고 바글바글 끓으면, 속을 채운 양파를 넣고 찜국물을 끼얹어가며 속까지 충분히 익힙니다.\n\n5. 마무리: 찜국물이 자작해지면 물녹말을 넣어 걸쭉하게 만든 후 불을 끄고 그릇에 담아냅니다.','\n',char(10)));
INSERT INTO recipes VALUES(27,'왕갈비버섯전골','근육 유지에 필수적인 양질의 소고기 단백질과 혈당 상승을 억제하는 식이섬유가 풍부한 다양한 버섯, 배추를 활용한 식단입니다. 포화지방이 많은 갈비의 기름기를 최대한 제거하여 혈관 건강까지 고려했습니다.','/static/027.png','당뇨','한식','고단백','왕갈비살 80g, 배추 35g, 느타리버섯 25g, 표고버섯 25g, 팽이버섯 10g, 무 15g,소금3g',195,8.0,18.0,10.0,1180.0,20,replace('1. 핏물 제거: 소고기 왕갈비는 흐르는 물에 20분 이상 담가 핏물을 깨끗이 제거합니다.\n\n2. 기름기 제거: 왕갈비의 기름을 최대한 제거한 후 끓는 물에 한 번 데쳐 곧바로 얼음물에 담가둡니다. (이 과정에서 불필요한 지방이 응고되어 제거하기 쉬워집니다.)\n\n3. 육수 내기: 데친 소고기 왕갈비를 찬물에서부터 다시 넣고 충분히 끓입니다.\n\n4. 육수 완성: 고기는 건져내고, 남은 국물은 소금으로 간을 하여 전골 육수로 준비합니다.\n\n5. 채소 세팅: 돌전골 냄비 바닥에 무를 깔고 그 위에 버섯, 배추, 버섯 순으로 보기 좋게 돌려 담습니다.\n\n6. 완성: 냄비 가운데에 준비한 왕갈비를 고명 형태로 올리고, 준비한 육수를 부어 한소끔 끓여냅니다.','\n',char(10)));
INSERT INTO recipes VALUES(28,'황태 전골','고단백 저지방 식품인 황태를 주재료로 하여 근육 손실을 막아주며, 다양한 버섯류와 채소를 통해 식이섬유를 충분히 섭취할 수 있습니다. 별도의 당분 없이 황태 머리 육수로 감칠맛을 내어 혈당 관리에 용이한 맑은 전골 요리입니다.','/static/028.png','당뇨','한식','해산물','황태 15g, 애느타리버섯 25g, 표고버섯 25g, 팽이버섯 25g, 양파 10g, 대파 10g, 청·홍고추 3g씩',125,10.0,18.0,1.5,1320.0,20,replace('1. 육수 준비: 마른 황태 머리는 차가운 물에 20분 정도 담가 이물질을 깨끗이 제거합니다.\n\n2. 육수 끓이기: 냄비에 불려진 황태 머리를 넣고 푹 끓여 육수를 낸 후, 소금으로 간을 합니다.\n\n3. 버섯 손질: 애느타리버섯은 결대로 손으로 찢고, 표고버섯은 채 썰어 준비합니다.\n\n4. 팽이버섯 손질: 팽이버섯은 밑동을 자르고 적당한 덩어리로 뜯어 놓습니다.\n\n5. 채소 손질: 양파는 채 썰고, 대파와 청·홍고추는 어슷썰기 하여 준비합니다.\n\n6. 세팅: 전골 냄비에 손질한 채소와 버섯을 보기 좋게 둘러 담습니다.\n\n7. 완성: 준비된 육수를 붓고 그 위에 황태 살을 고명으로 올려 한소끔 끓여 마무리합니다.','\n',char(10)));
INSERT INTO recipes VALUES(29,'우엉잡채월남쌈','식이섬유가 풍부하여 혈당 상승을 억제하는 우엉을 주재료로 사용하고, 설탕 대신 그린스위트를 활용해 당분 섭취를 최소화했습니다. 또한, 다양한 채소와 표고버섯을 곁들여 포만감은 높이면서도 칼로리 부담을 낮춘 건강한 별미 식단입니다.','/static/029.png','당뇨','한식','채식(비건)','우엉 40g, 당면 25g, 표고버섯 25g, 양파 10g, 청·홍고추 3g씩, 라이스페이퍼 4g,진간장 5g(1작은술), 그린스위트 1g(1작은술), 물 15g(1큰술), 식용유 5g(1작은술),참기름 5g(1작은술), 진간장 5g(1작은술), 통깨 2g(1/4큰술)',215,28.0,3.0,10.0,435.0,20,replace('1. 당면 준비: 당면은 찬물에 불렸다가 끓는 물에 삶아냅니다.\n\n2. 우엉 손질: 통우엉은 껍질을 벗기고 얇게 채 썰어 물에 담가 둡니다. (공기와의 접촉을 줄여 갈변을 방지합니다.)\n\n3. 우엉 전처리: 채 썬 우엉을 흐르는 물에 2~3회 씻어 쓴맛과 아린 맛을 제거한 후, 끓는 물에 데쳐 찬물에서 식히고 물기를 제거합니다.\n\n4. 우엉 볶기: 팬에 간장, 그린스위트, 물을 넣고 손질한 우엉을 볶습니다.\n\n5. 부재료 준비: 표고버섯, 양파, 청·홍고추는 채 썰어 준비한 뒤 각각 팬에 볶아줍니다.\n\n6. 버무리기: 삶은 당면과 볶은 우엉, 표고버섯, 채소들을 섞어 참기름, 간장, 통깨로 양념합니다.\n\n7. 월남쌈 완성: 미지근한 물에 담가 부드러워진 라이스페이퍼에 준비된 우엉 잡채를 넣고 돌돌 말아 완성합니다.','\n',char(10)));
INSERT INTO recipes VALUES(30,'죽순 양배추롤 전골','식이섬유가 풍부하여 당 흡수를 늦춰주는 죽순과 양배추를 주재료로 사용하고, 지방이 적은 소고기 양지를 곁들여 단백질 균형을 맞춘 저칼로리 전골 요리입니다.','/static/030.png','당뇨','한식','채식(비건)','죽순 70g, 양배추 70g, 소고기 40g, 양파 10g, 당근 10g, 대파 40g,소금 1g (1/3작은술), 후추 약간',135,12.0,11.0,5.0,450.0,20,replace('1. 소고기 손질: 소고기는 흐르는 물에 30분 이상 담가 핏물을 깨끗이 제거합니다.\n\n2. 초벌 데치기: 소고기를 끓는 물에 넣고 한 번 데쳐냅니다.\n\n3. 고기 삶기: 데친 소고기를 찬물에서부터 다시 끓여 충분히 익힙니다.\n\n4. 채소 데치기: 양배추와 죽순은 끓는 물에 살짝 데쳐 준비합니다.\n\n5. 롤 만들기: 양배추의 부드러운 부분은 넓게 펴고, 딱딱한 부분은 안쪽에 넣어 말아서 한입 크기로 만듭니다.\n\n6. 고기 준비: 잘 익은 소고기는 결 방향대로 먹기 좋게 찢어서 준비합니다.\n\n7. 채소 손질: 모든 채소는 한입 크기로 썰어 준비합니다.\n\n8. 세팅 및 완성: 전골 냄비에 준비한 채소를 둘러 담고 중앙에 찢어둔 양지를 올린 후, 소금과 후추로 간을 하여 한소끔 끓여냅니다.\n\n','\n',char(10)));
